use std::env;
use std::fmt::Write as _;
use std::fs;
use std::process;

struct Report {
    count: i64,
    name: String,
    note: String,
}

fn fail(message: impl AsRef<str>) -> ! {
    eprintln!("{}", message.as_ref());
    process::exit(1);
}

fn escape_json(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            '\u{08}' => escaped.push_str("\\b"),
            '\u{0c}' => escaped.push_str("\\f"),
            character if character <= '\u{1f}' => {
                let _ = write!(escaped, "\\u{:04x}", character as u32);
            }
            character => escaped.push(character),
        }
    }
    escaped
}

fn main() {
    let mut arguments = env::args();
    arguments.next();
    let path = match arguments.next() {
        Some(path) => path,
        None => fail("missing input path"),
    };
    if arguments.next().is_some() {
        fail("unexpected extra argument");
    }

    let input = match fs::read_to_string(&path) {
        Ok(input) => input,
        Err(error) => fail(format!("cannot read {}: {}", path, error)),
    };

    let mut name: Option<String> = None;
    let mut count: Option<i64> = None;
    let mut note: Option<String> = None;

    for (index, line) in input.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let (field, value) = match line.split_once('\t') {
            Some(parts) => parts,
            None => fail(format!("malformed field on line {}", index + 1)),
        };
        match field {
            "name" => {
                if name.is_some() {
                    fail("duplicate name field");
                }
                name = Some(value.to_owned());
            }
            "count" => {
                if count.is_some() {
                    fail("duplicate count field");
                }
                count = Some(match value.parse::<i64>() {
                    Ok(count) => count,
                    Err(_) => fail(format!("invalid count on line {}", index + 1)),
                });
            }
            "note" => {
                if note.is_some() {
                    fail("duplicate note field");
                }
                note = Some(value.to_owned());
            }
            _ => fail(format!("unknown field {:?} on line {}", field, index + 1)),
        }
    }

    let report = Report {
        count: count.unwrap_or_else(|| fail("missing count field")),
        name: name.unwrap_or_else(|| fail("missing name field")),
        note: note.unwrap_or_else(|| fail("missing note field")),
    };

    let name = escape_json(&report.name);
    let note = escape_json(&report.note);
    let mut output = String::new();
    let _ = write!(
        output,
        "{{\"count\":{},\"name\":\"{}\",\"note\":\"{}\"}}",
        report.count, name, note
    );
    println!("{}", output);
}
